1	package com.example.starter.calibration.service;
2	
3	import java.math.BigDecimal;
4	import java.time.Instant;
5	import java.util.List;
6	
7	import org.springframework.dao.DuplicateKeyException;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	import com.example.starter.calibration.api.ApiException;
12	import com.example.starter.calibration.api.dto.MeasurementResponse;
13	import com.example.starter.calibration.api.dto.SubmitMeasurementRequest;
14	import com.example.starter.calibration.model.Certificate;
15	import com.example.starter.calibration.model.Measurement;
16	import com.example.starter.calibration.model.MeasurementStatus;
17	import com.example.starter.calibration.repo.CertificateRepository;
18	import com.example.starter.calibration.repo.MeasurementRepository;
19	import com.example.starter.calibration.repo.ReleaseRepository;
20	
21	/**
22	 * 测量服务：提交（匹配唯一有效证书并固化计算结果）、历史明细、当前可用结果查询。
23	 */
24	@Service
25	public class MeasurementService {
26	
27	    private final MeasurementRepository measurements;
28	    private final CertificateRepository certificates;
29	    private final ReleaseRepository releases;
30	
31	    public MeasurementService(MeasurementRepository measurements,
32	                              CertificateRepository certificates,
33	                              ReleaseRepository releases) {
34	        this.measurements = measurements;
35	        this.certificates = certificates;
36	        this.releases = releases;
37	    }
38	
39	    /**
40	     * 提交测量。按测量时刻匹配唯一有效证书，无匹配返回 422；
41	     * 使用 BigDecimal 精确计算 a×读数+b，合格判断基于未舍入值且包含端点。
42	     * measurementKey 重复返回 409（幂等键冲突）。
43	     */
44	    @Transactional
45	    public MeasurementResponse submit(SubmitMeasurementRequest request) {
46	        String key = Inputs.requireText(request.measurementKey(), "measurementKey");
47	        String instrumentId = Inputs.requireText(request.instrumentId(), "instrumentId");
48	        Instant measuredAt = Inputs.requireInstant(request.measuredAt(), "measuredAt");
49	        BigDecimal reading = Inputs.requireDecimal(request.reading(), "reading");
50	        BigDecimal lower = Inputs.requireDecimal(request.lowerLimit(), "lowerLimit");
51	        BigDecimal upper = Inputs.requireDecimal(request.upperLimit(), "upperLimit");
52	        String submittedBy = Inputs.requireText(request.submittedBy(), "submittedBy");
53	        if (lower.compareTo(upper) > 0) {
54	            throw ApiException.badRequest("lowerLimit 不能大于 upperLimit");
55	        }
56	
57	        Certificate cert = certificates.findMatching(instrumentId, measuredAt)
58	                .orElseThrow(() -> ApiException.unprocessable(
59	                        "测量时刻无匹配的有效证书: instrument=" + instrumentId));
60	
61	        BigDecimal computed = cert.a().multiply(reading).add(cert.b());
62	        boolean passed = computed.compareTo(lower) >= 0 && computed.compareTo(upper) <= 0;
63	
64	        Measurement measurement = new Measurement(
65	                0L, key, instrumentId, measuredAt, reading, lower, upper, submittedBy,
66	                cert.id(), computed, passed, MeasurementStatus.PENDING, Instant.now());
67	        try {
68	            measurements.insert(measurement);
69	        } catch (DuplicateKeyException ex) {
70	            throw ApiException.conflict("DUPLICATE_MEASUREMENT_KEY", "测量键已存在: " + key);
71	        }
72	        return toDetail(measurements.findByKey(key).orElseThrow());
