    void twoInvalidationOrdersActivatingOverlappingClosureExactlyOneWins() throws Exception {
        buildScenario();
        long version = jdbc.queryForObject("SELECT version FROM domain_state WHERE id = 1", Long.class);

        // 两个针对同一失效根的失效单，各自先由一名质量人员确认
